INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q7837260', 'Treaty of Titalia', 'The Treaty of Titalia was signed between the chogyal (monarch) of the Kingdom of Sikkim and the British East India Company (EIC). The treaty, which was negotiated by Captain Barre Latter in February 1817, guaranteed security of Sikkim by the British and returned Sikkimese land annexed by the Nepalese over the centuries.', 1817, 2, 10, NULL, NULL, NULL, 'day', '10 February 1817', 39, 'https://en.wikipedia.org/wiki/Treaty_of_Titalia'),
  ('Q7045496', 'Noakhali riots', 'The Noakhali riots were a series of semi-organised massacres, rapes, and abductions of Hindus, combined with looting and arson of Hindu properties, perpetrated by Muslim mobs in the districts of Noakhali in the Chittagong Division of the eastern part of British Bengal (present-day Bangladesh) from October to November 1946, a year before India''s independence from British rule. It affected the areas under the Ramganj, Begumganj, Raipur, Lakshmipur, Chhagalnaiya, and Sandwip police stations in Noakhali district and the areas under the Hajiganj, Faridganj, Chandpur, Laksham, and Chauddagram…', 1946, 11, NULL, NULL, NULL, NULL, 'month', 'November 1946', 51, 'https://en.wikipedia.org/wiki/Noakhali_riots'),
  ('Q371394', 'Bangladesh Liberation War', 'The Bangladesh Liberation War (Bengali: মুক্তিযুদ্ধ, pronounced [mukt̪iɟud̪d̪ʱo]), also known as the Bangladesh War of Independence, was an armed conflict sparked by the rise of the Bengali nationalist and self-determination movement in East Pakistan, which resulted in the independence of Bangladesh with the help of India. The war began when the Pakistani military junta based in West Pakistan—under the orders of Yahya Khan—launched Operation Searchlight against East Pakistanis on the night of 25 March 1971, initiating the Bangladesh genocide.', 1971, 3, 26, 1971, 12, 16, 'day', '26 March 1971 – 16 December 1971', 80, 'https://en.wikipedia.org/wiki/Bangladesh_Liberation_War'),
  ('Q1430144', '1971 Dhaka University massacre', 'The 1971 Dhaka University massacre was the mass murder of students and teachers of the University of Dhaka in East Pakistan (present-day Bangladesh) by the Pakistan Army. On the night of 25–26 March 1971, under the orders of Yahya Khan, the Pakistan Army''s Eastern Wing Commander Tikka Khan initiated an attack on the university campus as the initial phase of Operation Searchlight, aiming to destroy what was considered the heart of Bengali nationalism.', 1971, NULL, NULL, NULL, NULL, NULL, 'year', '1971', 43, 'https://en.wikipedia.org/wiki/1971_Dhaka_University_massacre'),
  ('Q2916113', 'Bangladesh genocide', 'The Bangladesh genocide was the ethnic cleansing of Bengalis residing in East Pakistan (now Bangladesh) during the Bangladesh Liberation War, perpetrated by the Pakistan Army and the Razakars militia. It began on 25 March 1971, as Operation Searchlight was launched by West Pakistan (now Pakistan) to militarily subdue the Bengali population of East Pakistan; the Bengalis comprised the demographic majority and had been calling for independence from the Pakistani state.', 1971, 3, 26, 1971, 12, 16, 'day', '26 March 1971 – 16 December 1971', 65, 'https://en.wikipedia.org/wiki/Bangladesh_genocide'),
  ('Q4871079', 'Battle of Garibpur', 'The Battle of Garibpur was fought between the Indian forces and Pakistani forces for the control of the village of Garibpur, now in Bangladesh. On 20 November 1971, Indian troops of the 14th Battalion of the Punjab Regiment with 14 supporting PT-76 tanks from the 45 Cavalry moved in to capture the areas around Garibpur in Pakistani territory.', 1971, 11, 20, 1971, 11, 21, 'day', '20 November 1971 – 21 November 1971', 34, 'https://en.wikipedia.org/wiki/Battle_of_Garibpur'),
  ('Q5116036', 'Chuknagar massacre', 'Chuknagar massacre (Bengali: চুকনগর গণহত্যা) was a massacre of approximately 10,000 to 12,000 Bengali Hindus committed by the Pakistan Army and local collaborators during the Bangladesh War of Independence in 1971. The massacre took place on 20 May 1971 at Dumuria in Khulna and it was one of the largest massacres during the war.', 1971, 5, 20, NULL, NULL, NULL, 'day', '20 May 1971', 39, 'https://en.wikipedia.org/wiki/Chuknagar_massacre'),
  ('Q117883823', 'Santahar massacre', 'The Santahar massacre (Bengali: সান্তাহার গণহত্যা, Urdu: سانتہار کا قتل عام) was a massacre of thousands of Bihari and non-Bengali men, women and children in the railway town of Santahar, Naogaon District, East Pakistan, carried out by the Mukti Bahini and Bengali mobs between March and April 1971 during the Bangladesh Liberation War.', 1971, 4, 17, NULL, NULL, NULL, 'day', '17 April 1971', 34, 'https://en.wikipedia.org/wiki/Santahar_massacre'),
  ('Q4855418', 'Bangladesh famine of 1974', 'The Bangladesh famine of 1974 (Bengali: চুয়াত্তরের দুর্ভিক্ষ, romanized: Cuāttōrēr Durbhikkhō) began in March 1974 and ended around December of the same year. The famine is considered one of the worst in the 20th century; it was caused by government mismanagement, food grain smuggling to neighboring countries and flooding along the Brahmaputra River among other issues, resulting in high mortality.', 1974, 3, NULL, 1974, 12, NULL, 'month', 'March 1974 – December 1974', 47, 'https://en.wikipedia.org/wiki/Bangladesh_famine_of_1974'),
  ('Q39086822', '15 August 1975 Bangladesh coup d''état', 'A military coup was launched in Bangladesh on 15 August 1975, by mid-ranking army officers in order to assassinate President Sheikh Mujibur Rahman. Sheikh Mujibur Rahman, also known as Bangabandhu (lit. ''Friend of Bengal'') or Mujib, was the country''s founding president, but post-independence his administration grew corrupt and reportedly ''increasingly authoritarian'' until he formed a ''one-party state'' led by the socialist Bangladesh Krishak Sramik Awami League.', 1975, 8, 15, NULL, NULL, NULL, 'day', '15 August 1975', 37, 'https://en.wikipedia.org/wiki/15_August_1975_Bangladeshi_coup_d''%C3%A9tat'),
  ('Q48733313', '7 November 1975 Bangladesh coup d''état', 'The 7 November 1975 Bangladeshi coup d''état, also known as the Sipahi–Janata Revolution (Bengali: সিপাহী–জনতার বিপ্লব, romanized: Sipāhī–Jônôtār Biplôb, lit. ''Soldier–People''s Revolution''), was launched by left-wing soldiers (Sipahi) of Biplobi Shainik Sangstha (BSS) under the leadership of Lt. Col.', 1975, 11, 7, NULL, NULL, NULL, 'day', '7 November 1975', 34, 'https://en.wikipedia.org/wiki/7_November_1975_Bangladeshi_coup_d''%C3%A9tat'),
  ('Q48733969', '3 November 1975 Bangladesh coup d''état', 'The 3 November 1975 Bangladeshi coup d''état was organised by Brig. Khaled Mosharraf against President Khondaker Mostaq Ahmad to remove him from the presidency and the assassins of Sheikh Mujibur Rahman from power: Capt.', 1975, 11, 3, NULL, NULL, NULL, 'day', '3 November 1975', 37, 'https://en.wikipedia.org/wiki/3_November_1975_Bangladeshi_coup_d''%C3%A9tat'),
  ('Q4393801', 'Bangladeshi presidential confidence referendum, 1977', 'A national vote of confidence on President Ziaur Rahman was held in Bangladesh on 30 May 1977. Voters were asked, "Do you have confidence in President Major General Ziaur Rahman and the policies and programs adopted by him?".', 1977, 5, 30, NULL, NULL, NULL, 'day', '30 May 1977', 34, 'https://en.wikipedia.org/wiki/1977_Bangladeshi_presidential_confidence_referendum'),
  ('Q4580321', '1982 Bangladesh coup d''état', 'Lieutenant General Hussain Muhammad Ershad, the then-chief of Army Staff of Bangladesh, led a coup d''état against the then-president of Bangladesh, Abdus Sattar, in 1982. After serving initially as the Chief Martial Law Administrator and installing a civilian president, Justice A. F. M. Ahsanuddin Chowdhury, Ershad assumed presidency in 1983 and ruled until 1990.', 1982, 3, 24, NULL, NULL, NULL, 'day', '24 March 1982', 34, 'https://en.wikipedia.org/wiki/1982_Bangladeshi_coup_d''%C3%A9tat'),
  ('Q24950646', '1990 Bangladesh mass uprising', 'A mass uprising took place in Bangladesh on 4 December 1990 and led to the fall of General Hussain Muhammad Ershad. The uprising, popularly known in Bangladesh as the ʼ90''s Anti-Authoritarian Movement, was the result of a series of popular protests that started on 10 October 1990 to topple General Ershad, who came to power in 1982 by imposing martial law and replaced a democratically elected president, Abdus Sattar, through a bloodless coup.', 1990, 10, 10, NULL, NULL, NULL, 'day', '10 October 1990', 34, 'https://en.wikipedia.org/wiki/1990_Bangladesh_mass_uprising'),
  ('Q130754', '2004 Indian Ocean earthquake', 'On 26 December 2004, at 07:58:53 local time (UTC+7), a Mw 9.2–9.3 earthquake struck with its epicenter off the west coast of Aceh, in northern Sumatra, Indonesia. The undersea megathrust earthquake, known in the scientific community as the Sumatra–Andaman earthquake, was caused by a rupture along the fault boundary between the Burma plate and the Indian plate, and reached a maximum Mercalli intensity of IX in some areas.', 2004, 12, 26, NULL, NULL, NULL, 'day', '26 December 2004', 85, 'https://en.wikipedia.org/wiki/2004_Indian_Ocean_earthquake_and_tsunami'),
  ('Q2385882', 'Bangladesh Rifles revolt', 'The Bangladesh Rifles revolt, also known as the Pilkhana massacre or Pilkhana tragedy, was a mutiny that took place on 25–26 February 2009 in Dhaka, when a group of Bangladesh Rifles (BDR) personnel seized the force''s headquarters in Pilkhana. The mutineers killed Director General Shakil Ahmed, 56 other army officers and 17 civilians; fired on bystanders; held officers and their families hostage; and looted and vandalised property.', 2009, 2, NULL, NULL, NULL, NULL, 'month', 'February 2009', 57, 'https://en.wikipedia.org/wiki/Bangladesh_Rifles_revolt'),
  ('Q571891', '2011 Sikkim earthquake', 'The 2011 Sikkim earthquake (also known as the 2011 Himalayan earthquake) occurred with a moment magnitude of 6.9 and was centered within the Kanchenjunga Conservation Area, near the border of Nepal and the Indian state of Sikkim, at 18:10 IST on Sunday, 18 September. The earthquake was felt across northeastern India, Nepal, Bhutan, Bangladesh, and southern Tibet.', 2011, 9, 18, NULL, NULL, NULL, 'day', '18 September 2011', 55, 'https://en.wikipedia.org/wiki/2011_Sikkim_earthquake'),
  ('Q136935', '2012 Dhaka fire', 'The 2012 Dhaka garment factory fire broke out on 24 November 2012, in the Tazreen Fashion factory in the Ashulia district on the outskirts of Dhaka, Bangladesh. At least 117 people were confirmed dead in the fire, and over 200 were injured, making it the deadliest factory fire in the nation''s history.', 2012, 11, 24, NULL, NULL, NULL, 'day', '24 November 2012', 47, 'https://en.wikipedia.org/wiki/2012_Dhaka_garment_factory_fire'),
  ('Q383991', '2012 Indian Ocean earthquakes', 'The 2012 Indian Ocean earthquakes were magnitude 8.6 and 8.2 Mw undersea earthquakes that struck near the Indonesian province of Aceh on 11 April at 15:38 local time. Initially, authorities feared that the initial earthquake would cause a tsunami and warnings were issued across the Indian Ocean; however, these warnings were subsequently cancelled.', 2012, 4, 11, NULL, NULL, NULL, 'day', '11 April 2012', 66, 'https://en.wikipedia.org/wiki/2012_Indian_Ocean_earthquakes'),
  ('Q4337415', '2013 Shahbag protests', 'The 2013 Shahbag protests were widespread demonstrations held in Bangladesh. On 5 February 2013, protests ignited in Shahbag, Bangladesh, fuelled by the call for the execution of the convicted war criminal Abdul Quader Mollah.', 2013, 2, 9, NULL, NULL, NULL, 'day', '9 February 2013', 50, 'https://en.wikipedia.org/wiki/2013_Shahbag_protests'),
  ('Q19830062', 'April 2015 Nepal earthquake', 'The April 2015 Nepal earthquake (also known as the Gorkha earthquake) killed 8,962 people and injured 21,952 across the countries of Nepal, India, China and Bangladesh. It occurred at 11:56 Nepal Standard Time on Saturday 25 April 2015, with a magnitude of Mw 7.8–7.9 or Ms 8.1 and a maximum Mercalli Intensity of X (Extreme).', 2015, 4, 25, NULL, NULL, NULL, 'day', '25 April 2015', 82, 'https://en.wikipedia.org/wiki/April_2015_Nepal_earthquake'),
  ('Q25250323', '2016 Gulshan, Dhaka attack', 'The July 2016 Dhaka attack or Holey Artisan terrorist attack took place on the night of 1 July 2016, at 21:20 Bangladesh Standard Time (UTC+06:00), when five Islamic State (IS) terrorists took hostages and opened fire on the Holey Artisan Bakery in Gulshan Thana jurisdiction in Dhaka, Bangladesh. The terrorists entered the bakery with crude bombs, machetes, and pistols, and took several dozen hostages, including foreign nationals.', 2016, 7, 1, NULL, NULL, NULL, 'day', '1 July 2016', 64, 'https://en.wikipedia.org/wiki/July_2016_Dhaka_attack'),
  ('Q28128756', '2017 Tripura earthquake', 'A magnitude 5.7 earthquake struck India 20 km (12 mi) east north-east of Ambassa in the state of Tripura on 3 January 2017 with a maximum observed intensity of 6-7 EMS. It struck at 2:39 pm local time (09:09 UTC), and was centered in an isolated area. The estimated depth was 32.0 km.', 2017, 1, 3, NULL, NULL, NULL, 'day', '3 January 2017', 37, 'https://en.wikipedia.org/wiki/2017_Tripura_earthquake'),
  ('Q55897756', '2018 Bangladesh road safety protests', 'A series of public protests in Bangladesh advocating improved road safety were held from 29 July to 10 August 2018. They were sparked by the deaths of two high-school students in Dhaka struck by a bus operated by an unlicensed driver who was racing to collect passengers.', 2018, 7, 29, NULL, NULL, NULL, 'day', '29 July 2018', 45, 'https://en.wikipedia.org/wiki/2018_Bangladesh_road-safety_protests'),
  ('Q61783440', '2019 Dhaka fire', 'On 20 February 2019, a fire broke out in Dhaka, Bangladesh following a road accident between a pickup van and a private car. After the collision, the car''s gas cylinder exploded.', 2019, 2, 20, NULL, NULL, NULL, 'day', '20 February 2019', 43, 'https://en.wikipedia.org/wiki/February_2019_Dhaka_fire'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q106150159', 'March 2021 Rohingya refugee-camp fire', 'On 22 March 2021, a fire that had started during the late afternoon in the Balukhali refugee camp in Cox''s Bazar, Bangladesh, destroyed a large portion of the camp, killed over a dozen people, and left nearly a thousand injured or missing. Thought to have begun when gas cylinders used for cooking exploded, 100 firemen fought the blaze, which burned for around eight hours until midnight.', 2021, 3, 22, NULL, NULL, NULL, 'day', '22 March 2021', 41, 'https://en.wikipedia.org/wiki/March_2021_Rohingya_refugee-camp_fire'),
  ('Q110253606', '2021 Bangladesh ferry fire', 'On 24 December 2021, the passenger ferry MV Avijan-10 caught fire on the Sugandha River, near the town of Jhalokati, in southern Bangladesh. The incident resulted in at least 40 deaths and more than 100 injuries.', 2021, 12, 24, NULL, NULL, NULL, 'day', '24 December 2021', 53, 'https://en.wikipedia.org/wiki/2021_Bangladesh_ferry_fire'),
  ('Q112221848', '2022 India–Bangladesh floods', 'Beginning in May 2022, deadly floods hit northeastern India and Bangladesh. Over 9 million people in both countries have been affected, and around 300 people were killed.', 2022, 5, 23, NULL, NULL, NULL, 'day', '23 May 2022', 43, 'https://en.wikipedia.org/wiki/2022_India%E2%80%93Bangladesh_floods'),
  ('Q112245187', '2022 Sitakunda fire', 'On the night of 4 June 2022, a fire and subsequent explosions at a container depot in Sitakunda Upazila, Chittagong District, Bangladesh killed at least 47 people and injured around 450 others. The incident occurred at BM Container Depot in the Kadamrasul area of Sitakunda Upazila.', 2022, 6, 4, NULL, NULL, NULL, 'day', '4 June 2022', 50, 'https://en.wikipedia.org/wiki/2022_Sitakunda_fire'),
  ('Q127378229', '2024 Bangladesh quota reform movement', 'The 2024 Bangladesh quota reform movement was a series of anti-government and pro-democracy protests in Bangladesh, spearheaded primarily by university students. Initially focused on restructuring quota-based systems for government job recruitment, the movement expanded against what many perceived as an authoritarian government when government-associated groups carried out the July massacre of protesters and civilians, most of whom were students.', 2024, 6, 6, 2024, 8, 3, 'day', '6 June 2024 – 3 August 2024', 70, 'https://en.wikipedia.org/wiki/2024_Bangladesh_quota_reform_movement'),
  ('Q128401697', 'Non-cooperation movement (2024)', 'The non-cooperation movement, also known as the one-point movement, was a disinvestment movement and a mass uprising against the Awami League-led government of Bangladesh, initiated within the framework of the 2024 Bangladesh quota reform movement. The sole demand of this movement was the resignation of Prime Minister Sheikh Hasina and her cabinet.', 2024, 8, 4, 2024, 8, 5, 'day', '4 August 2024 – 5 August 2024', 57, 'https://en.wikipedia.org/wiki/Non-cooperation_movement_(2024)'),
  ('Q129322778', 'July massacre', 'The July massacre was the violent suppression and mass killings in Bangladesh during the July Uprising from 6 June to 5 August 2024. Triggered by the reinstatement of a controversial quota system and widespread public dissatisfaction, the crackdown was carried out by the government led by the Awami League, its affiliated groups such as the Chhatra League, and various law-enforcement agencies.', 2024, 7, NULL, NULL, NULL, NULL, 'month', 'July 2024', 34, 'https://en.wikipedia.org/wiki/July_massacre'),
  ('Q130255015', 'July Revolution', 'The July Uprising, also known as the July Mass Uprising, Student-People''s Uprising, July Revolution, Gen Z Revolution, or Monsoon Revolution was a mass uprising in Bangladesh in 2024. Starting in early–June 2024, the uprising concluded with the resignation of Sheikh Hasina-led Awami League government on 5 August 2024, ending its 15 year-long regime.', 2024, 7, 1, 2024, 8, 5, 'day', '1 July 2024 – 5 August 2024', 55, 'https://en.wikipedia.org/wiki/July_Uprising'),
  ('Q132861153', 'Aftermath of the July Revolution', 'Significant political, constitutional, and social changes in Bangladesh followed the July Uprising of 2024 and the resignation of Prime Minister Sheikh Hasina. The uprising was initially sparked by widespread public protests and calls for reform, led to major changes in Bangladesh''s political landscape.', 2024, 8, 5, NULL, NULL, NULL, 'day', '5 August 2024', 26, 'https://en.wikipedia.org/wiki/Aftermath_of_the_July_Uprising'),
  ('Q135433157', '2025 Dhaka fighter jet crash', 'On 21 July 2025, a Chengdu J-7 aircraft operated by the Bangladesh Air Force (BAF) crashed shortly after takeoff into the Milestone School campus in the Uttara neighbourhood of Dhaka, Bangladesh, while classes were in session. Investigations found that the cause of the crash was pilot error, resulting in a loss of control of the aircraft.', 2025, 7, 21, NULL, NULL, NULL, 'day', '21 July 2025', 57, 'https://en.wikipedia.org/wiki/2025_Dhaka_Chengdu_J-7_crash'),
  ('Q136891140', '2025 Bangladesh earthquake', 'On 21 November 2025, at 10:38:26 BST (UTC+6), a moment magnitude 5.4 earthquake struck near Dhaka, Bangladesh, followed by at least four aftershocks. At least 10 people died and nearly 630 others suffered injuries.', 2025, 11, 21, NULL, NULL, NULL, 'day', '21 November 2025', 45, 'https://en.wikipedia.org/wiki/2025_Bangladesh_earthquake');
